const fs = require('fs');
const q = $json.query || {};
const b = $json.body || {};
const entry = {
  ts: new Date().toISOString(),
  button: q.button || b.button || 'unknown',
  test: q.test || b.test || 'unknown',
  method: $json.method || 'POST',
  query: q,
  body_keys: Object.keys(b)
};
fs.appendFileSync('/miru-data/spike_ntfy_log.jsonl', JSON.stringify(entry) + '\n');
return [{ json: entry }];
